mapper.select:
SELECT e.id, e.request_user_id AS requestUserId, u.name AS requestUserName, u.phone AS requestUserPhone, e.type, e.response_admin_id AS responseAdminId, a.name AS responseAdminName, e.call_range AS callRange, e.call_time AS callTime, e.call_position AS callPosition, e.call_longitude AS callLongitude, e.call_latitude AS callLatitude, e.target_position AS targetPosition, e.status, e.create_time AS createTime, e.update_time AS updateTime FROM emergency_call e LEFT JOIN user_info u ON e.request_user_id = u.id LEFT JOIN admin_info a ON e.response_admin_id = a.id WHERE 1=1
AND e.status = #{query.status}
AND e.type = #{query.type}
AND e.call_time >= #{query.startTime}
AND e.call_time <= #{query.endTime}
ORDER BY e.call_time DESC

SELECT e.id, e.request_user_id AS requestUserId, u.name AS requestUserName, u.phone AS requestUserPhone, e.type, e.response_admin_id AS responseAdminId, a.name AS responseAdminName, e.call_range AS callRange, e.call_time AS callTime, e.call_position AS callPosition, e.call_longitude AS callLongitude, e.call_latitude AS callLatitude, e.target_position AS targetPosition, e.status, e.create_time AS createTime, e.update_time AS updateTime FROM emergency_call e LEFT JOIN user_info u ON e.request_user_id = u.id LEFT JOIN admin_info a ON e.response_admin_id = a.id WHERE e.response_admin_id = #{adminId}
AND e.status = #{status}
AND e.call_time >= #{startTime}
AND e.call_time <= #{endTime}
ORDER BY e.call_time DESC
